Inversion of $L$ and $Q_b$ profiles
Let the functional space
       ${\mathcal Y}$ be the set of functions $f\in \mathcal C^\infty({{\mathbb R}},{{\mathbb R}})$ such that
\begin{equation}\label{Y}
    \forall k\in \mathbb{N},\ \exists C_k,\, r_k>0,\ \forall y\in {{\mathbb R}},\quad |f^{(k)}(y)|\leq C_k (1+|y|)^{r_k} {e^{-|y|}},
\end{equation}
and $L$ be the linearized operator close to $Q$ given by \fref{deflplus}. We claim:

\begin{lemma}[Invertibility of $L$]
\label{lemmainvert}
{\rm (i)} There exists a unique $\Yz\in \mathcal Y$, even, such that
\begin{equation} \label{YQ}
L \Yz= 5  Q^4 ,\quad
(Q,\Yz)=-\frac 34 \int Q  .
\end{equation}
{\rm (ii)} There exists a unique function $P$ such that $P' \in \mathcal{Y}$ and
\begin{equation}
\label{eq:23}
 (L  P)'={\Lambda} Q, \ \  \lim_{y \to -\infty}   P(y) = \frac 12 \int Q,  \ \ \lim_{y \to +\infty}   P(y) =0,
 \end{equation}
 \begin{equation}
 \label{PQ}
 (P, Q) = \frac 1{16} \left(\int Q\right)^2 > 0,\quad (P,  Q')=0.
 \end{equation}
\end{lemma}
\begin{proof}
Note that the existence and uniqueness of $\Yz$ follows readily from standard properties of the operator $L$ (see e.g. \cite{MMR1}).






Moreover,
$$
(Q,\Yz)= -\frac 12 (L\Lambda Q,\Yz) =-\frac 12(\Lambda Q,5Q^4 )
 =-\frac 34 \int Q^5=-\frac 34 \int Q.
$$






















Part (ii)   is taken from \cite{MMR1}, Proposition 2.2.
\end{proof}

A simple consequence of Lemma \ref{lemmainvert} (ii) is the existence of a one parameter family of approximate self similar profiles $b\mapsto Q_b$, $|b|\ll 1$, which provide the leading order deformation of the ground state profile $Q=Q_{b=0}$ in the blow up regimes.  More precisely, let $\chi\in {\cal C}^{\infty}({\mathbb R})$ be such that $0\leq \chi \leq 1$, $\chi'\geq 0$ on $\mathbb{R}$,
$\chi\equiv 1$ on $[-1,+\infty)$, $\chi\equiv 0$ on $(-\infty,-2]$, and define
\begin{equation}\label{defgamma} 
\chi_b(y)= \chi\left(|b|^{\gamma} {y} \right),\ \ \gamma = \frac 34.
\end{equation}
The following Lemma is proved in \cite{MMR1}:

\begin{lemma}[Approximate self-similar profiles $Q_b$, \cite{MMR1}]
\label{cl:2}
Let 
\begin{equation}\label{eq:210}
\quad 
Q_b(y) = Q(y) + b \chi_b(y)   P (y).
\end{equation}
Then:\\
{\rm (i) Estimates on $Q_b$:} For all $y \in \mathbb{R}$,
\begin{align}
&	|Q_b(y)|\lesssim  e^{-|y|} + |b| \left(  {\mathbf{1}}_{[-2,0]}(|b|^\gamma y) +  e^{-\frac {|y|}{2}} \right),
\label{eq:001}\\
&	|Q_b^{(k)}(y)|\lesssim  e^{-|y|} +   |b|  e^{-\frac {|y|}{2}} +|b|^{1+k \gamma} {\mathbf{1}}_{[-2,-1]}(|b|^\gamma y),\quad  \text{for $k\geq 1$}.
\label{eq:002}
\end{align}
\noindent
{\rm (ii) Equation of $Q_b$:} let
\begin{equation}\label{eq:201}
-\Psi_b=\left(Q_b''- Q_b+ Q_b^5\right)'+b {\Lambda} Q_b,
\end{equation}
then, for all $y\in \mathbb{R}$,
\begin{align}
& |\Psi_b(y)|\lesssim |b|^{1+ \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y) 
+  b^2  \left(e^{-\frac {|y|} 2}+ {\mathbf{1}}_{[- 2,0]}(|b|^{\gamma}y) \right),\label{eq:202}
\\
& |\Psi_b^{(k)}(y)|\lesssim    |b|^{1+ (k+1) \gamma}  {\mathbf{1}}_{[-2 ,-1]}(|b|^{\gamma}y)  + b^2   e^{-\frac {|y|} 2} ,\quad 
 \text{for $k\geq 1$}. \label{eq:203}
\end{align}
{\rm (iii) Mass and energy properties of $Q_b$:}
\begin{align}
& \left|\int Q_b^2 - \left( \int Q^2 + 2b \int PQ \right)\right| \lesssim |b|^{2-\gamma}, \label{eq:204}\\
& \left| E(Q_b) + b \int PQ\right|\lesssim b^2 .
\label{eq:205}
\end{align}
\end{lemma}

