\label{defcobeta}
c_0=-\frac {\int Q}2(\theta-1)(2\theta-1)^{\theta-1}.
\end{equation}
Given $s>s_0$, $(b(s),\l(s),x(s))\in \RR^*_+\times \RR^*_+\times \RR$, we define:
 $$
g(s) =\frac {b(s)}{\l^2(s)} + \frac 4{\int Q} c_0   \l^{-\frac 32}(s) x^{-\theta}(s),\quad
f(s) =   \l^{\frac 12} (s) + \frac 2 {\int Q} c_0 \frac {1}{\theta-1} {x^{-\theta+1}(s)}.
$$
Let  $(\varphi_i)_{i=1,2},\psi$  be smooth functions such that:
\begin{eqnarray}
\label{defphi1bis}
\varphi_i(y) =\left\{\begin{array}{lll}e^{y}\ \ \mbox{for} \ \   y<-1,\\
 1+y  \ \ \mbox{for}\ \ -\frac 12<y<\frac 12,\\ 
 y^i\ \ \mbox{for}\ \ \mbox{for}\ \ y>2,
 \end{array}\right.  \ \ \varphi_i'(y) >0, \ \ \forall y\in \RR,
\end{eqnarray}
\begin{eqnarray}
\label{defphi2}
\psi(y) =\left\{\begin{array}{ll} e^{2y}\ \ \mbox{for}   \ \ y<-1,\\
 1  \ \ \mbox{for}\ \ y>-\tfrac 12,\end{array}\right.  \ \ \psi'(y) \geq 0 \ \ \forall y\in \RR.
\end{eqnarray}
Let $B> 100$ and
 $$\psi_B(y)=\psi\left(\frac yB\right), \ \ \varphi_{i,B}=\varphi_i\left(\frac yB\right), \ \ i=1,2,$$ 
 and define the following norms on $\e$
  \begin{equation}\label{eq:no}
{\mathcal{N}_i}  (s)  = \int  \varepsilon_y^2(s,y) \psi_{B}(y)dy + \int  \varepsilon^2(s,y) \varphi_{i,B}(y)   dy, 
\end{equation} 
\begin{equation}\label{eq:noloc}
{\mathcal{N}_{i,\rm loc}} (s)  =    \int\varepsilon^2 (s,y)     \varphi'_{i,B} (y) dy,\quad i=1,2.
\end{equation}
\\
We now claim the following bootstrap Proposition which is the heart of the analysis:

\begin{proposition}[Bootstrap]
\label{PR:BS}
Let $s_0=s_0(\beta)>1$ large enough and set
\begin{equation}
\label{initixzero}
x_0= x (s_0)=  \frac 1{(1-\beta)}{s_0^{1-\beta}}.
\end{equation}
Let  $\e_0\in H^1$ be such that 
\begin{equation}\label{A2}
s_0^{10}\left[ \int_{y>0} y^{10} \e^2_0(y) dy+\|\e_0\|^2_{H^1} \right]<1, \quad (\e_0, y {\Lambda}   Q )=(\e_0,\Lambda Q) =(\e_0,Q)=0.\end{equation}
Then, there exists  
\begin{equation}\label{estimation2}
(\l_0,b_0)\in\mathcal D =\left \{(\l,b) \ : \ | \l - s_0^{-\beta}| \leq s_0^{-\beta - \frac 1{10}},
\ |b  - \beta s_0^{-1}| \leq s_0^{-1-\frac 1{10}}\right\},
\end{equation} 
such that the solution of \eqref{kdv} with initial data
\begin{equation}\label{defu0}
u_0(x)   =  \frac 1{\l^{\frac 12}_0} \left( Q_{b_0} + \l^{\frac 12}_0 q_0(s_0,x_0) \Yz+ \e_0   \right) \left( \frac {x-x_0}{\l_0}\right)
+q_0(s_0,x)
\end{equation}
has a decomposition $(b(s),\l(s),x(s), \e(s))$ as in Proposition \ref{le:2} which satisfies\footnote{recall that $s=s(t)$ is the rescaled time \fref{rescaledtime}.} on $[s_0,+\infty)$:
$$\leqno{\rm (BS1)}\quad
\left(|g(s)|  s^{1 - 2 \beta + \frac 15} \right)^2+ 
\left(|f(s)| s^{\frac \beta 2 + \frac 1{10}}\right)^2\leq 1; 
$$
$$\leqno{\rm (BS2)}\quad 
|b(s)|\leq   {10} s^{-1},
\
\frac 1{10} s^{-\beta}\leq \l(s) \leq 10 s^{-\beta},
\  
\frac 1{10} s^{1-\beta} \leq (1-\beta) x(s) \leq 10 s^{1-\beta};
$$
$$\leqno{\rm (BS3)}\quad
\int_{y>0}y^{10}\e^2(s,y)dy\leq 10 \l^{-10} ,\quad 
\mathcal N_{i}(s) \leq s^{-\frac 52},\quad \|\e(s)\|_{H^1} \lesssim \delta(\alpha^*).
$$
Moreover,
\begin{equation}\label{sharp}
\left|  \frac {(1-\beta)}{s^{1-\beta}}  x (s) - 1\right|
+\left|  s^{\beta} \l(s) -1\right|
+\left| \frac {s}{\beta } b(s) -1\right|  \lesssim s^{-\frac 1{10}}, 
\end{equation}
\begin{equation}\label{sharpe}
\l^{-1} \|\e_y(s)\|_{L^2}+ \|\e(s)\|_{L^2} \lesssim 1.
\end{equation}
\end{proposition}
 Let us observe that \fref{sharp} now gives the leading order behavior of the scaling parameter $\lambda(s)=\frac{1}{s^{\beta}}(1+o(1))$, and the conclusion of Theorem \ref{th:1} now immediately follow from the change of variables \fref{rescaledtime} depending on the value of $\beta$ as in step (iv) of section \ref{vneovnoen}.\\

The rest of this section is therefore devoted to the proof of Proposition \ref{PR:BS}. First observe by uniqueness of the decomposition that
$$
b_0=b(s_0),\quad  \l(s_0)=\l_0 \quad x(s_0)=x_0, \quad \e(s_0)=\e_0.
$$
We now argue by contradiction, assuming that for all 
$(\l_0,b_0)\in \mathcal D$,    we have
$$
s^*(\l_0,b_0) := \sup \left\{
s\geq s_0 \hbox{ such that   (BS1)-(BS2)-(BS3) holds on $[s_0,s]$}
\right\} <+\infty.
$$
We will derive a contradiction by first closing the bootstrap bounds (BS1)-(BS2)-(BS3), and then finding a couple $(\l_0,b_0)$ using a topological argument.

}\label{AA}

Recall that  $c_0\in \RR$ and $\theta>1$ are  fixed,  $x_0\gg 1$ is to be taken large enough and $\qz$ is the solution of 
\begin{equation}\label{defqzA}
\partial_t \qz + \partial_x(\partial_x^2 \qz + \qz^5)=0,\quad
\qz(0,x)= f_0(x),
\end{equation}
where the function $f_0$ is   smooth and satisfies
\begin{equation}\label{deffzA}
f_0(x)= c_0 x^{-\theta} \hbox{ for $x>\frac {x_0}2$},\quad
f_0(x)=0 \hbox{ for $x<\frac {x_0}4$}, 
\end{equation}
\begin{equation}\label{estfzA}
\hbox{ for all $x\in \RR$, for all $k\geq 0$},\quad 
\left|\frac {d^{k}f_0}{dx^k} (x)\right| \lesssim c_0 |x|^{-\theta - k}.
\end{equation}

First, for $x_0$ large enough, $\|f_0\|_{L^2}$ is small and it follows from the $L^2$ and $H^s$ Cauchy theory (Corollary 2.9 in \cite{KPV})
that $q_0$ is global and bounded in $H^s$ for all $s\geq 0$, with
$$\sup_t\|q_0(t)\|_{H^s}\lesssim \delta(x_0^{-1}).$$


We define
$$
\qu(t,x)  = \qz(t,x) -f_0(x),
$$
\begin{equation}\label{defquA}
\partial_t \qu + \partial_x(\partial_x^2 \qu + (\qu+f_0)^5-f_0^5)=F_0,\quad
\qu(0,x)= 0, 
\end{equation}
where
$$
F_0 = -\partial_x^3 f_0 - \partial_x(f_0^5).
$$

For any $\bar \theta\geq 0$, define a smooth function $\varphi_{\bar \theta}$ such that
\begin{equation}\label{dfphiu}
\varphi_{\bar \theta}(x) = x^{\bar \theta}  \text{ for $x\geq 4$},\quad
\varphi_{\bar \theta}(x) =  e^{\frac x8}   \text{ for $x\leq 0$},\quad
\varphi'\geq 0,\  \varphi'''\leq \frac 14 \varphi' \text{ on $\RR$}.
\end{equation}
For 
$$
0\leq \theta_1< 2 \theta+4, \quad \theta_1 \neq 2 \theta+3,
$$
    set
\begin{align*}
M_{\theta_1}(t)& = \int q_1^2(t) \varphi_{\theta_1}\left( x - \frac t 4 - \frac {x_0} 4\right) dx,
\\
E_{\theta_1}(t) &= \int \left( (\partial_x q_1)^2(t) -\frac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5\right)   \right)\varphi_{\theta_1+2}\left( x - \frac t 4 - \frac {x_0} 4 \right) dx,\\\
F_{\theta_1,k}(t) &= \int (\partial_x^k q_1)^2(t) \varphi_{\theta_1+2k}\left( x - \frac t 4 - \frac {x_0} 4\right) dx, \ k\geq 2.
\end{align*}

We differentiate $M_{\theta_1}(t)$ (omitting the variable $x - \frac t 4 - \frac {x_0} 4$ for the function $\varphi_{\theta_1}$):
\begin{align*}
M_{\theta_1}'(t) & = - 3 \int (\partial_x q_1)^2 \varphi_{\theta_1}' -\frac 14 \int q_1^2 \varphi_{\theta_1}'
+ \int q_1^2 \varphi_{\theta_1}'''  \\ &
+ 2 \int \left((q_1+f_0)^5 - f_0^5\right) (q_1 \varphi_{\theta_1})_x + 
2 \left|\int F_0 q_1 \varphi_{\theta_1} \right|\\
& \leq - 3 \int (\partial_x q_1)^2 \varphi_{\theta_1}' -\frac 3{16} \int q_1^2 \varphi_{\theta_1}'
- 2 \int \left[ \frac {(q_1+f_0)^6}6 - \frac   {f_0^6} 6-(q_1+f_0)^5 q_1\right] \varphi_{\theta_1}'
\\ & + 2 \int \left[ (q_1+f_0)^5 - 5 q_1^4 f_0-f_0^5\right] f_0' \varphi_{\theta_1}
+ 2 \left|\int F_0^2  \frac {\varphi_{\theta_1}^2}{\varphi_{\theta_1}'} \right|^{\frac 12}
 \left| \int q_1^2 \varphi_{\theta_1}'\right|^{\frac 12} \\
& \leq - 3 \int (\partial_x q_1)^2 \varphi_{\theta_1}' -\frac 1 8 \int q_1^2 \varphi_{\theta_1}' 
+\delta(x_0^{-1}) \int q_1^2 \varphi_{\theta_1}'   + C \int F_0^2  \frac {\varphi_{\theta_1}^2}{\varphi_{\theta_1}'}     .
\end{align*}
Thus, for $x_0$ large enough, we have obtained
$$
M_{\theta_1}'(t) + \frac 1{10}  \int \left[ (\partial_x q_1)^2 + q_1^2 \right] \varphi_{\theta_1}'
\lesssim \int F_0^2  \frac {\varphi_{\theta_1}^2}{\varphi_{\theta_1}'}   .
$$
For $x_0$ large enough,
\begin{align}
   \int F_0^2  \frac {\varphi_{\theta_1}^2} {\varphi_{\theta_1}'}\left( x - \frac t 4 - \frac {x_0} 4\right)
& \lesssim    \int_{x>\frac t4 + \frac {x_0} 4 + 4} x^{-2(\theta+3)} \left( x - \frac t 4 - \frac {x_0} 4 \right)^{\theta_1+1}  \nonumber   \\
&  + \int_{\frac t8 + \frac {x_0} 8 < x<\frac t4 + \frac {x_0} 4 + 4}   x^{-2(\theta+3)}
+\int_{x< \frac t8 + \frac {x_0} 8} e^{\frac 18 (x-\frac t 4 - \frac {x_0} 4 )}\nonumber
\\ & \lesssim   (t+x_0)^{ \theta_1 -2 \theta-4 } . \label{Fzero}
\end{align}
Therefore, using also $M_{\theta_1}(0)=0$, we find by integration:
\begin{equation}\label{eqM}
M_{\theta_1}(t) +  \int_0^t\int \left[ (\partial_x q_1)^2 + q_1^2 \right] \varphi_{\theta_1}' \lesssim 
\begin{cases} (t+x_0)^{ \theta_1 -2 \theta-3 } & \hbox{if $0<\theta_1 {-}2 \theta{-}3<1$}  \\
  x_0^{ \theta_1 -2 \theta-3 } & \hbox{if $\theta_1 {-}2 \theta{-}3<0$} \end{cases} \end{equation}

We argue similarly for $E_{\theta_1}(t)$. 
\begin{align*}
E_{\theta_1}'(t) & = 2 \int \partial_t q_1 \left[ - \partial_x^2 q_1 - \left((q_1+f_0)^5 - f_0^5\right)\right] \varphi_{\theta_1+2}\\
&  - 2 \int \partial_t q_1 \partial_x q_1 \varphi_{\theta_1+2}'
- \frac  14 \int\left[ (\partial_x q_1)^2(t) -\frac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5\right)   \right]\varphi_{\theta_1+2}'
\\ &= - \int \left[ \partial_x^2 q_1 + \left((q_1+f_0)^5 - f_0^5\right) \right]^2 \varphi_{\theta_1+2}'\\
& - 2 \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5\right] F_0\varphi_{\theta_1+2}\\
& + 2 \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5\right]_x \partial_x q_1 \varphi_{\theta_1+2}'
  - 2 \int F_0 \partial_x q_1 \varphi_{\theta_1+2}' 
\\ &- \frac  14 \int\left[ (\partial_x q_1)^2(t) -\frac 13 \left( (q_1+f_0)^6 - f_0^6 - 6 q_1 f_0^5\right)   \right]\varphi_{\theta_1+2}'.
\end{align*}
We use the following computations and estimates
\begin{align*}
&\left| \int \left[ \partial_x^2 q_1 + (q_1 + f_0)^5 - f_0^5\right] F_0\varphi_{\theta_1+2} \right| \\
& \lesssim 
\left|  \int \partial_x q_1 (F_0 \varphi_{\theta_1+2})_x \right| + \left| \int \left[  (q_1 + f_0)^5 - f_0^5\right] F_0\varphi_{\theta_1+2}\right| \\
& \lesssim \frac 1{100} \int   (\partial_x q_1)^2  \varphi_{\theta_1+2}'
+\frac 1{100} \int    q_1^2  \varphi_{\theta_1}'
\\ & + C \int \left(|\partial_x F_0|^2 \frac {\varphi_{\theta_1+2}^2}{\varphi_{\theta_1+2}'}
+ |F_0|^2 \varphi_{\theta_1+2}' + |F_0|^2 \frac {f_0^8 \varphi_{\theta_1+2}^2}{\varphi_{\theta_1}'}\right).
\end{align*}
\begin{align*}
2 \int \partial_x^3 q_1 \partial_x q_1 \varphi_{\theta_1+2}' 
& = - 2 \int (\partial_x^2 q_1)^2 \varphi_{\theta_1+2}' + \int (\partial_x q_1)^2 \varphi_{\theta_1+2}'''\\
& \leq - 2 \int (\partial_x^2 q_1)^2 \varphi_{\theta_1+2}' + \frac 14 \int (\partial_x q_1)^2 \varphi_{\theta_1+2}'.
\end{align*}
\begin{align*}
& \left| 2 \int \left[ (q_1+f_0)^5 - f_0^5\right]_x \partial_x q_1 \varphi_{\theta_1+2}' \right|\\
& =\left| 10 \int (\partial_x q_1)^2 (q_1+f_0)^4 \varphi_{\theta_1+2}'
+10 \int \left( (q_1+f_0)^4 - f_0^4\right) \partial_x f_0  \partial_x q_1 \varphi_{\theta_1+2}'\right|\\
& \leq \frac 1{100} \int (\partial_x q_1)^2 \varphi_{\theta_1+1}' + C \int q_1^2 \varphi_{\theta_1}'.
\end{align*}
\begin{align*}
2 \left| \int F_0 \partial_x q_1 \varphi_{\theta_1+2}'\right| \leq
\frac 1{100} \int (\partial_x q_1)^2 \varphi_{\theta_1+1}' + C \int |F_0|^2\varphi_{\theta_1+2}'.
\end{align*}
Combining these estimates, and using the expression of $F_0$ as in \eqref{Fzero}, we find
\begin{align*}
E_{\theta_1}'(t) \leq - \int (\partial_x^2 q_1)^2 \varphi_{\theta_1+2}' - \frac 1{10} \int (\partial_x q_1)^2 \varphi_{\theta_1+2}' 
+ C\int q_1^2 \varphi_{\theta_1}' + C  (t+x_0)^{ \theta_1 -2 \theta-4 }.
\end{align*}
By integration, and using \eqref{eqM},
\begin{align}
& E_{\theta_1}(t) + \frac 1{10} \int_0^t \int \left[(\partial_x^2 q_1)^2 + (\partial_x q_1)^2 \right]\varphi_{\theta_1+2}'\nonumber \\
& \lesssim \begin{cases} (t+x_0)^{ \theta_1 -2 \theta-3 } & \hbox{if $0<\theta_1 {-}2 \theta{-}3<1$}  \\
  x_0^{ \theta_1 -2 \theta-3 } & \hbox{if $\theta_1 {-}2 \theta{-}3<0$} \end{cases}\label{eqE}
\end{align}

We look for an estimate on $\partial_x q_1(t)$ from the above estimate on $E_{\theta_1}(t)$.
Note first that
\begin{align}
\|q_1^2 \sqrt{\varphi_{\theta_1+2}} \|_{L^\infty} &\lesssim
\int_x^{+\infty} |q_1| |\partial_x q_1| \sqrt{\varphi_{\theta_1+2}}
+ \int_x^{+\infty} |q_1|^2 \frac {\varphi_{\theta_1+2}'}{\sqrt{\varphi_{\theta_1+2}}}\nonumber\\
& \lesssim \left( \int q_1^2\right)^{\frac 12} \left( \int |\partial_x q_1|^2  \varphi_{\theta_1+2}
+ \int |q_1|^2 \varphi_{\theta_1}\right)^{\frac 12},\label{Linfty}
\end{align}
so that
\begin{align*}
\int q_1^6 \varphi_{\theta_1+2} \leq \|q_1^2 \sqrt{\varphi_{\theta_1+2}} \|_{L^\infty}^2
\int q_1^2 \lesssim 
\left( \int q_1^2\right)^2 \left( \int |\partial_x q_1|^2  \varphi_{\theta_1+2}
+ M_{\theta_1}(t)\right) .
\end{align*}
Also,
$$
\int q_1^2 f_0^4 \varphi_{\theta_1+2} \lesssim \int q_1^2 \varphi_{\theta_1} = M_{\theta_1}(t).
$$
Thus,
\begin{align}
E_{\theta_1}(t) & \geq \int (\partial_x q_1)^2 \varphi_{\theta_1+2} - C \int (q_1^6 + q_1^2 f_0^4) \varphi_{\theta_1+2}\nonumber\\
& \geq \frac 12 \int (\partial_x q_1)^2 \varphi_{\theta_1+2} - C M_{\theta_1}(t),\label{eq6}
\end{align}
and so
\begin{align}
&\int (\partial_x q_1)^2 \varphi_{\theta_1+2}+ \int_0^t \int \left[(\partial_x^2 q_1)^2 + (\partial_x q_1)^2 \right]\varphi_{\theta_1+2}'\nonumber \\
&\lesssim \begin{cases} (t+x_0)^{ \theta_1 -2 \theta-3 } & \hbox{if $0<\theta_1 {-}2 \theta{-}3<1$}   \\
  x_0^{ \theta_1 -2 \theta-3 } & \hbox{if $\theta_1 {-}2 \theta{-}3<0$} \end{cases} \label{eqEbb}\end{align}

Note also that for  any $x$,
\begin{align}
  q_1^2(t,x) \varphi_{\theta_1+1}\left( x - \frac t4-\frac {x_0} 4\right) 
& \lesssim \int_x^{+\infty}  |q_1| |\partial_x q_1|  \varphi_{\theta_1+1} 
+\int_x^{+\infty} |q_1|^2 \varphi_{\theta_1+1}' \nonumber \\
& \lesssim 
\int    |\partial_x q_1|^2  \varphi_{\theta_1+2} 
+\int  |q_1|^2 \varphi_{\theta_1} ,
\label{linfty}\end{align}
and, with $\theta_1 = 2 \theta+ \frac {15}4$,
using the properties of $\varphi_{\theta_1+1}$, for $x>\frac 12 (t+x_0)$, 
\begin{equation}\label{A11}
|q_1(t,x)| \lesssim x^{- (\frac {\theta_1}2 +\frac 12 )} t^{\frac 38} =x^{- (\theta+\frac {19}8)} t^{\frac 38}
  \lesssim   x^{- (\theta+2)}.
\end{equation}


Finally, we briefly treat the case of higher order derivatives.
We use an induction argument, assuming at the rank $k$  that for all
$1\leq k'<k$,  for all $x$, $t$
\begin{align}\nonumber
& \int_0^t \int (\partial_x^{k'} q_1)^2(t) \varphi_{\theta_1+2k'}' \left( x - \frac t4-\frac {x_0} 4\right) dt
+
\int (\partial_x^{k'} q_1(t))^2 \varphi_{\theta_1+2k'}\left( x - \frac t4-\frac {x_0} 4\right) \\ &\label{ply2}
+|\partial_x^{k'-1} q_1(t)|^2 \varphi_{\theta_1+2k'-1}\left( x - \frac t4-\frac {x_0} 4\right) 
  \lesssim \begin{cases} (t+x_0)^{ \theta_1 -2 \theta-3 } & \hbox{if $0<\theta_1 {-}2 \theta{-}3<1$}  \\
  x_0^{ \theta_1 -2 \theta-3 } & \hbox{if $\theta_1 {-}2 \theta{-}3<0$} \end{cases}
\end{align}
we prove the same estimates for $k'=k$ using $F_{\theta_1,k}$.

Indeed, by simple computation:
\begin{align*}
F_{\theta_1,k}'(t) & = 2 \int (\partial_x^k  q_1)_t (\partial_x^k q_1) \varphi_{\theta_1+2k} -
\frac 12 \int (\partial_x^k q_1)^2 \varphi_{\theta_1+2k}'\\
& = - 2 \int (\partial_x^{k+3} q_1) (\partial_x^k q_1) \varphi_{\theta_1+2k} 
- 2 \int \partial_x^{k+1} \left( (q_1+f_0)^5 -f_0^5\right) \partial_x^k q_1 \varphi_{\theta_1+2k}\\
& - \frac 12 \int (\partial_x^k q_1)^2 \varphi_{\theta_1+2k}'+ \int (\partial_x^k F_0) (\partial_x^k q_1) \varphi_{\theta_1+2k} \\
& \leq - 3 \int (\partial_x^{k+1} q_1)^2 \varphi_{\theta_1+2k}' - \frac 14 \int (\partial_x^k q_1)^2 \varphi_{\theta_1+2k}'\\
& + 2 \int \partial_x^k \left( (q_1+f_0)^5 - f_0^5\right) 
\left( (\partial_x^{k+1} q_1) \varphi_{\theta_1+2k} + (\partial_x^k q_1) \varphi_{\theta_1+2k}'\right)
\\ & + \int (\partial_x^k F_0) (\partial_x^k q_1) \varphi_{\theta_1+2k}.
\end{align*}
We claim, arguing as \eqref{Fzero},
$$
\left| \int (\partial_x^k F_0) (\partial_x^k q_1) \varphi_{\theta_1+2k} \right| 
\leq \frac 1{100}\int (\partial_x^k q_1)^2  \varphi_{\theta_1+2k}'+ C t^{\theta_1-2 \theta -4}.
$$
Next, we claim
\begin{align}
& \left|\int \partial_x^k \left( (q_1+f_0)^5 - f_0^5\right) 
\left( (\partial_x^{k+1} q_1) \varphi_{\theta_1+2k} + (\partial_x^k q_1) \varphi_{\theta_1+2k}'\right)\right|\nonumber \\
& \leq \frac 1{100}\int (\partial_x^{k+1} q_1) \varphi_{\theta_1+2k}'+\frac 1{100}\int (\partial_x^{k} q_1) \varphi_{\theta_1+2k}'+\sum_{k'=0}^{k-1} \int (\partial_x^{k'} q_1)^2  \varphi_{\theta_1+2k'}' .\label{ply3}
\end{align}


Indeed, looking for example at the purely nonlinear term in $q_1$, we have
\begin{align*}
&\left|\int  \partial_x^k (q_1^5)  (\partial_x^{k+1} q_1) \varphi_{\theta_1+2k} \right|
+ \left|\int  \partial_x^k (q_1^5)  (\partial_x^{k} q_1) \varphi_{\theta_1+2k}' \right|
\\
&\leq C \int \left(\partial_x^k (q_1^5)\right)^2 \frac {\varphi_{\theta_1+2k}^2}{\varphi_{\theta_1+2k}'}
+ \frac 1{200}\int (\partial_x^{k} q_1)^2 \varphi_{\theta_1+2k}'+\frac 1{200} \int (\partial_x^{k+1} q_1)^2  \varphi_{\theta_1+2k}' ,
\end{align*}
and
\begin{align*}
& \int \left(\partial_x^k (q_1^5)\right)^2 \frac {\varphi_{\theta_1+2k}^2}{\varphi_{\theta_1+2k}'}
\lesssim
\int \left(\partial_x^k (q_1^5)\right)^2 \varphi_{\theta_1+ 2 k_1+2k_2+2k_3+2k_4+2k_5+1}\\
